import { useEffect, useRef, useState } from 'react'
import workerUrl from 'pdfjs-dist/legacy/build/pdf.worker.min.mjs?url'

// WebKitGTK has no dependable built-in PDF viewer. Render the exact server-generated bytes locally.
export function PdfProof({ base64 }: { base64: string }) {
  const holder = useRef<HTMLDivElement>(null), [error, setError] = useState('')
  useEffect(() => {
    let canceled = false, destroy: (() => Promise<void>) | undefined
    setError(''); holder.current?.replaceChildren()
    void (async () => {
      const pdfjs = await import('pdfjs-dist/legacy/build/pdf.mjs')
      if (canceled) return
      pdfjs.GlobalWorkerOptions.workerSrc = workerUrl
      const task = pdfjs.getDocument({ data: Uint8Array.from(atob(base64), (c) => c.charCodeAt(0)) })
      destroy = () => task.destroy()
      const pdf = await task.promise
      for (let number = 1; number <= pdf.numPages; number++) {
        if (canceled || !holder.current) break
        const page = await pdf.getPage(number), viewport = page.getViewport({ scale: 1.5 })
        const canvas = document.createElement('canvas'); canvas.width = Math.ceil(viewport.width); canvas.height = Math.ceil(viewport.height)
        canvas.setAttribute('role', 'img'); canvas.setAttribute('aria-label', `Rendered résumé PDF page ${number} of ${pdf.numPages}`)
        holder.current.append(canvas)
        const context = canvas.getContext('2d'); if (!context) throw new Error('PDF drawing is unavailable.')
        await page.render({ canvasContext: context, canvas, viewport }).promise
      }
    })().catch((e) => { if (!canceled) setError(`PDF preview could not render: ${(e as Error).message}. The interactive preview and PDF export are still available.`) })
    return () => { canceled = true; void destroy?.() }
  }, [base64])
  return <>{error && <p role="alert" className="review-flag">{error}</p>}<div className="pdf-proof pdf-canvas-proof" ref={holder} aria-label="Rendered résumé PDF" /></>
}
